/**
 * OVYRA wordmark — approved identity v1.0 (asset W-02).
 *
 * Renders the official SVGs from /public/brand (generated by brand/source).
 * Both color versions are emitted and the active theme shows one of them,
 * so it also follows data-theme overrides. Aspect ratio 1202 : 275.
 */
const RATIO = 1202.1 / 275;
const HEIGHTS = { sm: 20, md: 28, lg: 44 } as const;

export function Wordmark({ size = 'md' }: { size?: keyof typeof HEIGHTS }) {
  const height = HEIGHTS[size];
  const width = Math.round(height * RATIO);
  return (
    <span
      className="inline-flex"
      role="img"
      aria-label="OVYRA"
      data-asset="W-02"
      data-asset-status="approved"
    >
      {/* eslint-disable-next-line @next/next/no-img-element -- static same-origin SVG, no optimization needed */}
      <img
        src="/brand/ovyra-wordmark-color-on-light.svg"
        alt=""
        width={width}
        height={height}
        className="theme-light-only"
        draggable={false}
      />
      {/* eslint-disable-next-line @next/next/no-img-element -- static same-origin SVG, no optimization needed */}
      <img
        src="/brand/ovyra-wordmark-color-on-dark.svg"
        alt=""
        width={width}
        height={height}
        className="theme-dark-only"
        draggable={false}
      />
    </span>
  );
}
